const migrations = [
  '20260101000001_first.sql',
  '20260101000002_second.sql',
  '20260101000003_third.sql',
];

function deploymentEvidence(overrides = {}) {
  const sha = 'a'.repeat(40);
  return {
    schema_version: 1,
    target: 'staging',
    status: 'APPLIED',
    recorded_at: '2026-09-01T00:00:00Z',
    branch: 'main',
    deploy_sha: sha,
